// Group by severity and collapse repeats BEFORE the model sees anything.
//
// Flapping is the normal failure mode of alerting: one sick host emits the same
// alert 400 times overnight. Sending all 400 to an LLM costs real money, blows
// the context window, and biases the summary toward whatever flapped loudest.
// Deduplicating first is both cheaper and more accurate.

const SEVERITY_ORDER = ['critical', 'high', 'warning', 'info'];

// The monitoring API may return a bare array or wrap it. Accept both shapes.
const raw = $input.all().flatMap((item) => {
  const j = item.json;
  if (Array.isArray(j)) return j;
  if (Array.isArray(j.alerts)) return j.alerts;
  if (Array.isArray(j.data)) return j.data;
  if (Array.isArray(j.result)) return j.result;
  return [j];
});

const normalizeSeverity = (s) => {
  const v = String(s || 'info').toLowerCase();
  if (['critical', 'crit', 'disaster', 'p1', 'sev1'].includes(v)) return 'critical';
  if (['high', 'error', 'major', 'p2', 'sev2'].includes(v)) return 'high';
  if (['warning', 'warn', 'average', 'p3', 'sev3'].includes(v)) return 'warning';
  return 'info';
};

// Identity of an alert = what is broken, on what, at what severity. Timestamps
// and instance ids are deliberately excluded from the key: they are what make
// duplicates look unique.
const dedupeKey = (a) =>
  [normalizeSeverity(a.severity), a.host || a.instance || a.resource || 'unknown', a.name || a.alertname || a.message || 'unnamed']
    .join('|')
    .toLowerCase();

const groups = new Map();

for (const a of raw) {
  const key = dedupeKey(a);
  const ts = a.timestamp || a.startsAt || a.clock || a.time || null;

  if (!groups.has(key)) {
    groups.set(key, {
      severity: normalizeSeverity(a.severity),
      host: a.host || a.instance || a.resource || 'unknown',
      name: a.name || a.alertname || a.message || 'unnamed',
      count: 0,
      first_seen: ts,
      last_seen: ts,
      sample_message: (a.message || a.description || a.summary || '').slice(0, 200),
    });
  }

  const g = groups.get(key);
  g.count += 1;
  if (ts) {
    if (!g.first_seen || ts < g.first_seen) g.first_seen = ts;
    if (!g.last_seen || ts > g.last_seen) g.last_seen = ts;
  }
}

const deduped = [...groups.values()].sort((x, y) => {
  const bySeverity = SEVERITY_ORDER.indexOf(x.severity) - SEVERITY_ORDER.indexOf(y.severity);
  return bySeverity !== 0 ? bySeverity : y.count - x.count;
});

const bySeverity = SEVERITY_ORDER.reduce((acc, s) => {
  acc[s] = deduped.filter((d) => d.severity === s).length;
  return acc;
}, {});

// Hard cap what reaches the model. 60 deduplicated groups is already more than
// a human will act on before lunch, and it bounds token spend on a bad night.
const MAX_GROUPS = 60;
const truncated = deduped.length > MAX_GROUPS;

return [
  {
    json: {
      window_start: $now.minus({ hours: 24 }).toISO(),
      window_end: $now.toISO(),
      total_alerts: raw.length,
      unique_alerts: deduped.length,
      counts_by_severity: bySeverity,
      truncated,
      groups: deduped.slice(0, MAX_GROUPS),
    },
  },
];
